      const data = await response.json();
      setImageGeneratedUrl(data.imageUrl);

      const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      const newImgItem = {
        url: data.imageUrl,
        prompt: imagePrompt,
        ratio: imageRatio,
        style: imageStyle,
        timestamp
      };
      
      const updatedList = [newImgItem, ...imageList].slice(0, 50);
